ALTER TABLE "InboxConversation" ADD COLUMN "channelConnectionId" TEXT;
CREATE TABLE "ChannelConnection" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"createdByMemberId" TEXT NOT NULL,"channel" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'custom_bridge',"displayName" TEXT NOT NULL,"externalAccountId" TEXT,"status" TEXT NOT NULL DEFAULT 'pending_verification',"capabilities" TEXT[] NOT NULL DEFAULT ARRAY['receive']::TEXT[],"signingSecretEncrypted" TEXT NOT NULL,"secretPrefix" TEXT NOT NULL,"webhookPathToken" TEXT UNIQUE NOT NULL,"config" JSONB,"lastVerifiedAt" TIMESTAMP(3),"lastEventAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChannelConnection_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE,CONSTRAINT "ChannelConnection_createdByMemberId_fkey" FOREIGN KEY ("createdByMemberId") REFERENCES "WorkspaceMember"("id") ON DELETE CASCADE);
CREATE TABLE "ChannelEvent" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"conversationId" TEXT,"messageId" TEXT UNIQUE,"providerEventId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'received',"normalizedPayload" JSONB,"errorCode" TEXT,"errorMessage" TEXT,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3),CONSTRAINT "ChannelEvent_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE,CONSTRAINT "ChannelEvent_connectionId_fkey" FOREIGN KEY ("connectionId") REFERENCES "ChannelConnection"("id") ON DELETE CASCADE,CONSTRAINT "ChannelEvent_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "InboxConversation"("id") ON DELETE SET NULL,CONSTRAINT "ChannelEvent_messageId_fkey" FOREIGN KEY ("messageId") REFERENCES "InboxMessage"("id") ON DELETE SET NULL,UNIQUE("connectionId","providerEventId"));
ALTER TABLE "InboxConversation" ADD CONSTRAINT "InboxConversation_channelConnectionId_fkey" FOREIGN KEY ("channelConnectionId") REFERENCES "ChannelConnection"("id") ON DELETE SET NULL;
CREATE INDEX "ChannelConnection_workspaceId_status_channel_idx" ON "ChannelConnection"("workspaceId","status","channel"); CREATE INDEX "ChannelConnection_workspaceId_provider_idx" ON "ChannelConnection"("workspaceId","provider"); CREATE INDEX "ChannelEvent_workspaceId_status_receivedAt_idx" ON "ChannelEvent"("workspaceId","status","receivedAt"); CREATE INDEX "ChannelEvent_connectionId_receivedAt_idx" ON "ChannelEvent"("connectionId","receivedAt"); CREATE INDEX "InboxConversation_workspaceId_channelConnectionId_status_idx" ON "InboxConversation"("workspaceId","channelConnectionId","status");
